  ('Card stock — type split vs headline total', 1, NULL, '2026-07', 1816057, 1927532, -111475, -5.783, 'METHODOLOGY_DIFFERENCE', 'The headline card total counts every valid card; the debit/credit split covers only cards with a payment function. The 111,475 card difference is cards issued with a cash function alone.');
insert into analytics.kpi_registry (kpi_id, display_name, business_definition, sql_formula, numerator, denominator, required_definition, frequency, aggregation_rule, valid_comparison_method, source_requirements, known_limitations) values
  ('pos_terminals', 'POS terminals', 'Card-accepting terminals in Kosovo at month end.', 'fact_pos_terminal_stock.terminal_count where observation_type=''MONTH_END''', 'terminal_count', NULL, 'pos_rm_allcards', 'monthly', 'STOCK — never summed across periods; averaged when a period figure is needed', 'Same calendar month, year on year', 'BQK Raport Mujor, sheet ''Terminalet për pagesa''', 'Series begins January 2025 and is not continuous with the annual report series.'),
  ('pos_transaction_count', 'POS transaction count', 'Card payments executed at POS terminals during the period.', 'sum(fact_pos_transactions.transaction_count)', 'transaction_count', NULL, 'any POS definition', 'monthly', 'FLOW — summed across periods', 'Equal month windows only', 'BQK Raport Mujor or Table 15, per selected definition', 'Three incompatible universes exist; the active one is always named.'),
  ('pos_transaction_value', 'POS transaction value', 'Value of card payments at POS terminals during the period.', 'sum(fact_pos_transactions.transaction_value)', 'transaction_value', NULL, 'any POS definition', 'monthly', 'FLOW — summed across periods', 'Equal month windows only', 'BQK Raport Mujor or Table 15', 'Table 15 values are published in EUR millions and scaled on load.'),
  ('transactions_per_average_pos', 'Transactions per average POS', 'Terminal productivity measured against the average terminal stock over the period, so growth in the network does not distort the denominator.', 'transaction_count / avg(terminal_count) over the same months', 'POS transaction count (flow)', 'Average POS terminal stock (stock, 12-month trailing mean)', 'pos_rm_allcards', 'monthly', 'Flow over averaged stock', 'Equal month windows only', 'Both sides from the same publication', 'Requires a monthly terminal series; unavailable before 2025.'),
  ('transactions_per_end_period_pos', 'Transactions per end-period POS', 'The same count divided by the closing terminal stock. Reported separately because it is not the same measure.', 'transaction_count / terminal_count at period end', 'POS transaction count (flow)', 'POS terminal stock at period end (stock)', 'pos_rm_allcards', 'monthly', 'Flow over closing stock', 'Equal month windows only', 'Both sides from the same publication', 'Understates productivity while the network is growing.'),
  ('value_per_average_pos', 'Value per average POS', 'Value processed per terminal over the period.', 'transaction_value / avg(terminal_count)', 'POS transaction value', 'Average POS terminal stock', 'pos_rm_allcards', 'monthly', 'Flow over averaged stock', 'Equal month windows only', 'Both sides from the same publication', 'Moves with ticket size as well as with usage.'),
  ('average_ticket', 'Average ticket', 'Average value of one card payment at a POS terminal.', 'transaction_value / transaction_count', 'POS transaction value', 'POS transaction count', 'same definition on both sides', 'monthly', 'Ratio of two flows from one universe', 'Any period, provided both sides share a definition', 'One publication for both numerator and denominator', 'None material.'),
  ('cards_issued', 'Cards issued', 'Valid payment cards in issue at month end.', 'fact_card_stock.cards_issued', 'cards_issued', NULL, 'pos_rm_allcards', 'monthly', 'STOCK — never summed', 'Same month, year on year', 'BQK Raport Mujor, sheet ''Kartelat bankare''', 'Scheme split covers Visa and Mastercard only.'),
  ('pos_per_1000_taxpayers', 'POS per 1,000 registered taxpayers', 'Terminal density against the registered taxpayer population. Taxpayers are NOT the same population as card-accepting businesses.', 'pos_terminals_estimated / entity_count * 1000', 'Estimated POS terminals, CITY grain, annual', 'ATK registered taxpayers, MUNICIPALITY grain, monthly average', 'pos_terminals_annual', 'annual', 'Stock over stock', 'Not comparable across years — one reference year only', 'BQK annual report + ATK Qarkullimi', 'Numerator is city grain and estimated from a chart; denominator is municipality grain and counts taxpayers, not merchants. A documented approximation.'),
  ('pos_per_eur1m_addressable', 'POS per €1m addressable turnover', 'Terminal density against turnover in sectors where a card at a point of sale is a plausible payment method.', 'pos_terminals_estimated / addressable_turnover * 1e6', 'Estimated POS terminals, CITY grain, annual', 'Addressable turnover, MUNICIPALITY grain, analytical classification', 'pos_terminals_annual', 'annual', 'Stock over flow — reported as a floor/ceiling range', 'Within one year only', 'BQK annual report + ATK Qarkullimi + sector mapping', 'Addressable turnover is an analytical classification, not an ATK measure. Wholesale and retail are one published sector, so the result is a range, not a point.'),
  ('turnover_per_taxpayer', 'Turnover per registered taxpayer', 'Declared turnover divided by the registered taxpayer count.', 'sum(turnover) / avg(entity_count)', 'ATK turnover (flow)', 'ATK taxpayers (stock, averaged)', NULL, 'annual', 'Flow over averaged stock', 'Year on year, same geography', 'ATK Qarkullimi', 'Taxpayers include entities with no turnover in the period.'),
  ('addressable_turnover', 'Addressable turnover', 'Turnover in sectors classified as plausibly card-addressable. An analytical classification, not an official ATK metric.', 'sum(turnover) where addressability_class in (...)', 'ATK turnover', NULL, NULL, 'annual', 'Sum of a flow within a classified subset', 'Year on year, same mapping version', 'ATK Qarkullimi + sector mapping v1', 'Reported as floor and ceiling because wholesale and retail are published as one section.'),
  ('bank_pos_share', 'POS share by bank', 'Each acquiring bank''s share of POS terminals, transactions and value within the KBA reporting universe.', 'fact_bank_pos.<measure> / sum(fact_bank_pos.<measure>)', 'bank measure', 'KBA reporting total', 'pos_kba_bank', 'periodic', 'Share within a single unlabelled period; never summed or trended', 'Between banks in the same extract only', 'KBA bank reporting, supplied as an aggregate extract', 'Supplied rather than downloaded, so there is no file hash. The extract carries no period label. Two banks report nothing and are excluded rather than counted as zero.'),
  ('fair_share_index', 'Fair Share Index', 'A bank''s share of POS value divided by its share of POS terminals. Above 1 means each terminal carries more value than the market average, below 1 means less.', '(value / total_value) / (terminals / total_terminals)', 'share of value', 'share of terminals', 'pos_kba_bank', 'periodic', 'Ratio of two shares within one extract', 'Between banks in the same extract only', 'KBA bank reporting', 'Identical to value per terminal indexed to the market, and factors exactly into transactions per terminal times average payment. Both factors are reported so the reason for a gap is visible. Says nothing about revenue: pricing is not published.'),
  ('bank_pos_productivity', 'Transactions per terminal by bank', 'Card payments per POS terminal, for each acquiring bank.', 'fact_bank_pos.transaction_count / fact_bank_pos.pos_terminals', 'transaction_count', 'pos_terminals', 'pos_kba_bank', 'periodic', 'Ratio within one bank and one extract', 'Between banks in the same extract only', 'KBA bank reporting', 'Not comparable with the BQK per-terminal figures elsewhere in this report: those count a different transaction universe over a known period, this one an unlabelled span.');
